//go:build darwin

package fuse

import "syscall"

// hostErrnoToLinux translates Darwin syscall errors into the Linux errno
// namespace used on the FUSE wire. Values not listed here are uncommon for
// filesystem operations and are reported as Linux EIO rather than exposing a
// misleading Darwin number to the guest.
func hostErrnoToLinux(e syscall.Errno) Status {
	switch e {
	case 0:
		return OK
	case syscall.EPERM:
		return Status(1)
	case syscall.ENOENT:
		return Status(2)
	case syscall.ESRCH:
		return Status(3)
	case syscall.EINTR:
		return Status(4)
	case syscall.EIO:
		return Status(5)
	case syscall.ENXIO:
		return Status(6)
	case syscall.E2BIG:
		return Status(7)
	case syscall.ENOEXEC:
		return Status(8)
	case syscall.EBADF:
		return Status(9)
	case syscall.ECHILD:
		return Status(10)
	case syscall.EDEADLK:
		return Status(35)
	case syscall.ENOMEM:
		return Status(12)
	case syscall.EACCES:
		return Status(13)
	case syscall.EFAULT:
		return Status(14)
	case syscall.ENOTBLK:
		return Status(15)
	case syscall.EBUSY:
		return Status(16)
	case syscall.EEXIST:
		return Status(17)
	case syscall.EXDEV:
		return Status(18)
	case syscall.ENODEV:
		return Status(19)
	case syscall.ENOTDIR:
		return Status(20)
	case syscall.EISDIR:
		return Status(21)
	case syscall.EINVAL:
		return Status(22)
	case syscall.ENFILE:
		return Status(23)
	case syscall.EMFILE:
		return Status(24)
	case syscall.ENOTTY:
		return Status(25)
	case syscall.ETXTBSY:
		return Status(26)
	case syscall.EFBIG:
		return Status(27)
	case syscall.ENOSPC:
		return Status(28)
	case syscall.ESPIPE:
		return Status(29)
	case syscall.EROFS:
		return Status(30)
	case syscall.EMLINK:
		return Status(31)
	case syscall.EPIPE:
		return Status(32)
	case syscall.EDOM:
		return Status(33)
	case syscall.ERANGE:
		return Status(34)
	case syscall.EAGAIN:
		return Status(11)
	case syscall.EINPROGRESS:
		return Status(115)
	case syscall.EALREADY:
		return Status(114)
	case syscall.ENOTSOCK:
		return Status(88)
	case syscall.EDESTADDRREQ:
		return Status(89)
	case syscall.EMSGSIZE:
		return Status(90)
	case syscall.EPROTOTYPE:
		return Status(91)
	case syscall.ENOPROTOOPT:
		return Status(92)
	case syscall.EPROTONOSUPPORT:
		return Status(93)
	case syscall.ESOCKTNOSUPPORT:
		return Status(94)
	case syscall.ENOTSUP:
		return Status(95)
	case syscall.ESTALE:
		return Status(116)
	case syscall.EPFNOSUPPORT:
		return Status(96)
	case syscall.EAFNOSUPPORT:
		return Status(97)
	case syscall.EADDRINUSE:
		return Status(98)
	case syscall.EADDRNOTAVAIL:
		return Status(99)
	case syscall.ENETDOWN:
		return Status(100)
	case syscall.ENETUNREACH:
		return Status(101)
	case syscall.ENETRESET:
		return Status(102)
	case syscall.ECONNABORTED:
		return Status(103)
	case syscall.ECONNRESET:
		return Status(104)
	case syscall.ENOBUFS:
		return Status(105)
	case syscall.EISCONN:
		return Status(106)
	case syscall.ENOTCONN:
		return Status(107)
	case syscall.ESHUTDOWN:
		return Status(108)
	case syscall.ETOOMANYREFS:
		return Status(109)
	case syscall.ETIMEDOUT:
		return Status(110)
	case syscall.ECONNREFUSED:
		return Status(111)
	case syscall.ELOOP:
		return Status(40)
	case syscall.ENAMETOOLONG:
		return Status(36)
	case syscall.EHOSTDOWN:
		return Status(112)
	case syscall.EHOSTUNREACH:
		return Status(113)
	case syscall.ENOTEMPTY:
		return Status(39)
	case syscall.ENOSYS:
		return Status(38)
	case syscall.EOVERFLOW:
		return Status(75)
	case syscall.ECANCELED:
		return Status(125)
	case syscall.EIDRM:
		return Status(43)
	case syscall.ENOMSG:
		return Status(42)
	case syscall.EILSEQ:
		return Status(84)
	case syscall.ENOATTR, syscall.ENODATA:
		return Status(61)
	case syscall.EBADMSG:
		return Status(74)
	case syscall.EMULTIHOP:
		return Status(72)
	case syscall.ENOLINK:
		return Status(67)
	case syscall.ENOSR:
		return Status(63)
	case syscall.ENOSTR:
		return Status(60)
	case syscall.EPROTO:
		return Status(71)
	case syscall.ETIME:
		return Status(62)
	default:
		return EIO
	}
}
